def base_string_uri(uri: str, host: str=None) ->str:
    if not isinstance(uri, str):
        raise ValueError('uri must be a string')

    if not uri or not uri.strip():
        raise ValueError('uri is empty')

    parsed = urlparse.urlsplit(uri)

    scheme = parsed.scheme
    if not scheme:
        raise ValueError('uri has no scheme')
    scheme = scheme.lower()

    if host is not None:
        if host.startswith('['):
            bracket_end = host.find(']')
            if bracket_end == -1:
                raise ValueError('invalid IPv6 host')
            host_part = host[:bracket_end + 1]
            rest = host[bracket_end + 1:]
            port_str = rest[1:] if rest.startswith(':') else None
        elif ':' in host:
            idx = host.rfind(':')
            host_part = host[:idx]
            port_str = host[idx+1:]
        else:
            host_part = host
            port_str = None

        host_lower = host_part.lower()

        if port_str is not None and port_str != '':
            try:
                port_num = int(port_str)
            except ValueError:
                raise ValueError('invalid port')
            if port_num <= 0 or port_num > 65535:
                raise ValueError('invalid port number')
            if (scheme == 'http' and port_num == 80) or (scheme == 'https' and port_num == 443):
                netloc_normalized = host_lower
            else:
                netloc_normalized = '{}:{}'.format(host_lower, port_num)
        else:
            netloc_normalized = host_lower
    else:
        if not parsed.netloc:
            raise ValueError('uri has no host')

        hostname = parsed.hostname
        if not hostname:
            raise ValueError('uri has no host')

        hostname = hostname.lower()

        try:
            port = parsed.port
        except ValueError:
            raise ValueError('invalid port in uri')

        if port is not None:
            if port <= 0 or port > 65535:
                raise ValueError('invalid port: {}'.format(port))
            if (scheme == 'http' and port == 80) or (scheme == 'https' and port == 443):
                netloc_normalized = hostname
            else:
                netloc_normalized = '{}:{}'.format(hostname, port)
        else:
            netloc_normalized = hostname

        netloc_normalized = netloc_normalized.replace(' ', '%20')

    if not netloc_normalized:
        raise ValueError('uri has no host')

    path = parsed.path
    if not path:
        path = '/'

    path = urlparse.quote(urlparse.unquote(path), safe='/-._~!$&\'()*+,;=:@%')

    return '{}://{}{}'.format(scheme, netloc_normalized, path)
